CREATE TABLE customers (id UUID PRIMARY KEY, subject VARCHAR(100) NOT NULL UNIQUE, display_name VARCHAR(100) NOT NULL, email VARCHAR(200) NOT NULL, phone VARCHAR(30), kyc_status VARCHAR(12) NOT NULL DEFAULT 'PENDING' CHECK (kyc_status IN ('PENDING','VERIFIED','REJECTED')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE bank_accounts (id UUID PRIMARY KEY, customer_id UUID REFERENCES customers(id), account_number VARCHAR(20) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL, type VARCHAR(12) NOT NULL CHECK(type IN ('SAVINGS','CURRENT','EQUITY')), status VARCHAR(10) NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','FROZEN','CLOSED')), currency CHAR(3) NOT NULL DEFAULT 'MYR' CHECK(currency='MYR'), balance NUMERIC(19,2) NOT NULL DEFAULT 0, held NUMERIC(19,2) NOT NULL DEFAULT 0 CHECK(held>=0), version BIGINT NOT NULL DEFAULT 0, CHECK(type='EQUITY' OR balance>=held));
CREATE INDEX accounts_customer_idx ON bank_accounts(customer_id);
CREATE TABLE beneficiaries (id UUID PRIMARY KEY, customer_id UUID NOT NULL REFERENCES customers(id), account_id UUID NOT NULL REFERENCES bank_accounts(id), nickname VARCHAR(80) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(customer_id,account_id));
CREATE TABLE transfers (id UUID PRIMARY KEY, customer_id UUID REFERENCES customers(id), source_id UUID NOT NULL REFERENCES bank_accounts(id), destination_id UUID NOT NULL REFERENCES bank_accounts(id), amount NUMERIC(19,2) NOT NULL CHECK(amount>0), currency CHAR(3) NOT NULL DEFAULT 'MYR', reference VARCHAR(40) NOT NULL UNIQUE, description VARCHAR(140) NOT NULL, status VARCHAR(12) NOT NULL CHECK(status IN ('SETTLED','REVERSED')), idempotency_key UUID NOT NULL, request_hash VARCHAR(100) NOT NULL, reversal_of UUID UNIQUE REFERENCES transfers(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(customer_id,idempotency_key), CHECK(source_id<>destination_id));
CREATE INDEX transfers_customer_date_idx ON transfers(customer_id,created_at DESC);
CREATE TABLE ledger_entries (id BIGSERIAL PRIMARY KEY, transfer_id UUID NOT NULL REFERENCES transfers(id), account_id UUID NOT NULL REFERENCES bank_accounts(id), amount NUMERIC(19,2) NOT NULL CHECK(amount<>0), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(transfer_id,account_id));
CREATE INDEX ledger_account_date_idx ON ledger_entries(account_id,created_at DESC);
CREATE TABLE account_holds (id UUID PRIMARY KEY, account_id UUID NOT NULL REFERENCES bank_accounts(id), amount NUMERIC(19,2) NOT NULL CHECK(amount>0), reason VARCHAR(100) NOT NULL, released_at TIMESTAMPTZ);
CREATE TABLE bank_statements (id UUID PRIMARY KEY, customer_id UUID NOT NULL REFERENCES customers(id), account_id UUID NOT NULL REFERENCES bank_accounts(id), date_from DATE NOT NULL, date_to DATE NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK(date_to>=date_from));
CREATE TABLE audit_logs (id BIGSERIAL PRIMARY KEY, actor VARCHAR(100) NOT NULL, action VARCHAR(50) NOT NULL, resource VARCHAR(100) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE outbox_events (id UUID PRIMARY KEY, aggregate_id UUID NOT NULL, customer_id UUID REFERENCES customers(id), event_type VARCHAR(60) NOT NULL, payload TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), published_at TIMESTAMPTZ, attempts INT NOT NULL DEFAULT 0);
CREATE INDEX outbox_pending_idx ON outbox_events(created_at) WHERE published_at IS NULL;
CREATE TABLE notification_records (event_id UUID PRIMARY KEY, customer_id UUID REFERENCES customers(id), event_type VARCHAR(60) NOT NULL, message TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE FUNCTION prevent_history_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Financial history is append-only'; END $$;
CREATE TRIGGER immutable_ledger BEFORE UPDATE OR DELETE ON ledger_entries FOR EACH ROW EXECUTE FUNCTION prevent_history_mutation();
CREATE TRIGGER immutable_audit BEFORE UPDATE OR DELETE ON audit_logs FOR EACH ROW EXECUTE FUNCTION prevent_history_mutation();
CREATE FUNCTION check_balanced_postings() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF (SELECT count(*) FROM ledger_entries WHERE transfer_id=NEW.transfer_id)<>2 OR (SELECT sum(amount) FROM ledger_entries WHERE transfer_id=NEW.transfer_id)<>0 THEN RAISE EXCEPTION 'Unbalanced ledger transfer'; END IF; RETURN NEW; END $$;
CREATE CONSTRAINT TRIGGER balanced_ledger AFTER INSERT ON ledger_entries DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION check_balanced_postings();
